package com.github.honestlygroovy.ophidiavenom;

import java.io.FileWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.util.Text;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import java.io.BufferedInputStream;
import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Collections;
import java.util.Set;
import java.util.stream.Collectors;

@Slf4j
public abstract class SoundFileManager
{

	private static final File DOWNLOAD_DIR = new File(RuneLite.RUNELITE_DIR.getPath() + File.separator + "ophidiavenom-sounds");
	private static final String DELETE_WARNING_FILENAME = "EXTRA_FILES_WILL_BE_DELETED_BUT_FOLDERS_WILL_REMAIN";
	private static final String SOUNDVERSION_FILENAME = "SOUNDVERSION";
	private static final File DELETE_WARNING_FILE = new File(DOWNLOAD_DIR, DELETE_WARNING_FILENAME);

	private static final HttpUrl RAW_GITHUB = HttpUrl.parse("https://raw.githubusercontent.com/honestlygroovy/ophidia-venom-sounds/sounds");

	private static boolean isUpdating = false;

	private static final Map<String, String[]> soundDirectoryMap = new ConcurrentHashMap<>();

	@SuppressWarnings("ResultOfMethodCallIgnored")
	public static void ensureDownloadDirectoryExists()
	{
		if (!DOWNLOAD_DIR.exists())
		{
			DOWNLOAD_DIR.mkdirs();
		}
		try
		{
			DELETE_WARNING_FILE.createNewFile();
		}
		catch (IOException ignored)
		{
		}
	}

	@SuppressWarnings("ResultOfMethodCallIgnored")
	public static void ensureSoundDirectoryExists(File soundDirectory)
	{
		if (!soundDirectory.exists())
		{
			soundDirectory.mkdirs();
		}
		File customDirectory = new File(soundDirectory, "custom");
		if (!customDirectory.exists())
		{
			customDirectory.mkdirs();
		}
		try
		{
			soundDirectory.createNewFile();
		}
		catch (IOException ignored)
		{
		}
	}

	public static void downloadAllMissingSounds(final OkHttpClient okHttpClient)
	{
		// Get set of existing files in our dir - existing sounds will be skipped, unexpected files (not dirs, some sounds depending on config) will be deleted
		assert RAW_GITHUB != null;
		HttpUrl versionUrl = RAW_GITHUB.newBuilder().addPathSegment(SOUNDVERSION_FILENAME).build();
		int latestVersion = getLatestVersion(okHttpClient, versionUrl);
		if (latestVersion == -1)
		{
			return;
		}

		int currentVersion = getCurrentVersion();

		if (latestVersion == currentVersion)
		{
			isUpdating = true;
			downloadMissingSounds(okHttpClient);
			isUpdating = false;
			return;
		}
		isUpdating = true;
		writeLatestVersion(latestVersion);

		for (String filename : getFilesPresent(DOWNLOAD_DIR))
		{
			File toDelete = new File(DOWNLOAD_DIR, filename);
			//noinspection ResultOfMethodCallIgnored
			toDelete.delete();
			log.warn("Ophidiavenom plugin deleted " + filename);
		}

		List<String> cleanedDirectories = new ArrayList<>();

		// Download any sounds that are not yet present but desired
		for (Sound sound : Sound.values())
		{
			String soundDirectory = sound.getDirectory();
			File soundDirectoryFile = new File(DOWNLOAD_DIR, soundDirectory);

			ensureSoundDirectoryExists(soundDirectoryFile);

			if (!cleanedDirectories.contains(soundDirectory))
			{
				Set<String> filesPresent = getFilesPresent(soundDirectoryFile);

				for (String filename : filesPresent)
				{
					File toDelete = new File(soundDirectoryFile, filename);
					//noinspection ResultOfMethodCallIgnored
					toDelete.delete();
					log.warn("Ophidiavenom plugin deleted " + filename);
				}

				cleanedDirectories.add(soundDirectory);
			}

			// End early if the sound couldn't be downloaded
			if (hasNotDownloadedSound(sound, okHttpClient))
			{
				return;
			}
		}

		isUpdating = false;
	}

	private static int getCurrentVersion()
	{
		int currentVersion = -1;
		try
		{
			currentVersion = getSoundVersion();
		}
		catch (IOException e)
		{
			// No current version available
			var soundVersionFile = new File(DOWNLOAD_DIR, SOUNDVERSION_FILENAME);
			try
			{
				//noinspection ResultOfMethodCallIgnored
				soundVersionFile.createNewFile();
			}
			catch (IOException e2)
			{
				log.error("Couldn't create soundversion file");
			}
		}
		return currentVersion;
	}

	private static int getLatestVersion(OkHttpClient okHttpClient, HttpUrl versionUrl)
	{
		int latestVersion = -1;
		try (Response res = okHttpClient.newCall(new Request.Builder().url(versionUrl).build()).execute())
		{
			if (res.body() != null)
			{
				latestVersion = Integer.parseInt(Text.standardize(res.body().string()));
			}
		}
		catch (IOException e)
		{
			log.error("Ophidiavenom Plugin could not download sound version", e);
		}
		return latestVersion;
	}

	private static boolean hasNotDownloadedSound(Sound sound, OkHttpClient okHttpClient)
	{
		String soundDirectory = sound.getDirectory();
		String soundResourceName = sound.getResourceName();
		File soundDirectoryFile = new File(DOWNLOAD_DIR.getPath(), sound.getDirectory());
		assert RAW_GITHUB != null;
		HttpUrl soundUrl = RAW_GITHUB.newBuilder().addPathSegment(soundDirectory).addPathSegment(soundResourceName).build();
		Path outputPath = Paths.get(soundDirectoryFile.getPath(), soundResourceName);
		ensureSoundDirectoryExists(soundDirectoryFile);
		try (Response res = okHttpClient.newCall(new Request.Builder().url(soundUrl).build()).execute())
		{
			if (res.body() != null)
			{
				Files.copy(new BufferedInputStream(res.body().byteStream()), outputPath, StandardCopyOption.REPLACE_EXISTING);
				log.warn("Ophidiavenom plugin downloaded " + sound.getResourceName());
				return false;
			}
			return true;
		}
		catch (IOException e)
		{
			log.error("Ophidiavenom Plugin could not download sounds", e);
			isUpdating = false;
			return true;
		}
	}

	private static void downloadMissingSounds(OkHttpClient okHttpClient)
	{
		for (Sound sound : Sound.values())
		{
			File soundFile = Paths.get(DOWNLOAD_DIR.getPath(), sound.getDirectory(), sound.getResourceName()).toFile();
			if (soundFile.exists())
			{
				continue;
			}
			// Download sound and if a sound couldn't get downloaded, return early.
			if (hasNotDownloadedSound(sound, okHttpClient))
			{
				return;
			}
		}
	}

	private static Set<String> getFilesPresent(File directory)
	{
		File[] downloadDirFiles = directory.listFiles();
		if (downloadDirFiles == null || downloadDirFiles.length == 0)
		{
			return new HashSet<>();
		}

		return Arrays.stream(downloadDirFiles)
			.filter(file -> !file.isDirectory())
			.map(File::getName)
			.filter(filename -> !DELETE_WARNING_FILENAME.equals(filename))
			.filter(filename -> !SOUNDVERSION_FILENAME.equals(filename))
			.collect(Collectors.toSet());
	}

	public static File getSoundStream(Sound sound) throws FileNotFoundException
	{
		String[] soundFileArray = getOrLoadSoundFiles(sound.getDirectory(), false);
		if (soundFileArray.length == 0)
		{
			return null;
		}
		return Paths.get(RandomSoundUtility.getRandomSound(soundFileArray)).toFile();
	}

	public static List<File> listCandidateSoundFiles(Sound sound)
	{
		return listCandidateSoundFiles(sound, false);
	}

	public static List<File> listCandidateSoundFiles(Sound sound, boolean refreshCache)
	{
		String[] soundFileArray = getOrLoadSoundFiles(sound.getDirectory(), refreshCache);
		if (soundFileArray.length == 0)
		{
			return Collections.emptyList();
		}

		return Arrays.stream(soundFileArray)
			.map(Paths::get)
			.map(Path::toFile)
			.collect(Collectors.toList());
	}

	public static void clearSoundDirectoryCache(Sound sound)
	{
		soundDirectoryMap.remove(sound.getDirectory());
	}

	public static void clearAllSoundDirectoryCaches()
	{
		soundDirectoryMap.clear();
	}

	public static List<File> listFilesInDirectory(String directory, boolean refreshCache)
	{
		String[] soundFileArray = getOrLoadSoundFiles(directory, refreshCache);
		if (soundFileArray.length == 0)
		{
			return Collections.emptyList();
		}
		return Arrays.stream(soundFileArray)
			.map(Paths::get)
			.map(Path::toFile)
			.collect(Collectors.toList());
	}

	public static File lookupFile(String directory, String fileName)
	{
		if (directory == null || fileName == null)
		{
			return null;
		}
		for (File file : listFilesInDirectory(directory, false))
		{
			if (fileName.equals(file.getName()))
			{
				return file;
			}
		}
		return null;
	}

	private static String[] getOrLoadSoundFiles(String directory, boolean refreshCache)
	{
		if (directory == null)
		{
			return new String[0];
		}

		if (refreshCache)
		{
			soundDirectoryMap.remove(directory);
		}

		return soundDirectoryMap.computeIfAbsent(directory, SoundFileManager::loadSoundFilesFromDisk);
	}

	private static String[] loadSoundFilesFromDisk(String directory)
	{
		File soundDirectoryPath = Paths.get(DOWNLOAD_DIR.getPath(), directory).toFile();
		File customSoundDirectoryPath = Paths.get(soundDirectoryPath.getPath(), "custom").toFile();
		File[] files = customSoundDirectoryPath.listFiles();
		if (files == null || files.length == 0)
		{
			files = soundDirectoryPath.listFiles();
		}

		String[] soundFileArray = files == null
			? new String[0]
			: Arrays.stream(files)
				.filter(file -> !file.isDirectory())
				.map(File::getAbsolutePath)
				.distinct()
				.toArray(String[]::new);

		return soundFileArray;
	}

	public static int getSoundVersion() throws IOException
	{
		File soundVersionFile = new File(DOWNLOAD_DIR, SOUNDVERSION_FILENAME);
		String soundVersionContent = Files.readString(soundVersionFile.toPath());
		return Integer.parseInt(soundVersionContent);
	}

	public static boolean getIsUpdating()
	{
		return isUpdating;
	}

	private static void writeLatestVersion(int version)
	{
		var soundVersionFile = new File(DOWNLOAD_DIR, SOUNDVERSION_FILENAME);
		try
		{
			FileWriter myWriter = new FileWriter(soundVersionFile);
			myWriter.write(String.valueOf(version));
			myWriter.close();
		}
		catch (IOException e)
		{
			log.error("Couldn't write latest soundversion");
		}
	}
}

package com.github.honestlygroovy.ophidiavenom.livestreams;

import com.github.honestlygroovy.ophidiavenom.ChatRightClickManager;
import com.github.honestlygroovy.ophidiavenom.OphidiavenomConfig;
import com.github.honestlygroovy.ophidiavenom.RightClickAction;
import com.github.honestlygroovy.ophidiavenom.Sound;
import com.github.honestlygroovy.ophidiavenom.sounds.LivestreamLiveSound;
import com.google.gson.Gson;
import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.util.Text;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import java.time.Duration;
import java.time.Instant;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

@Singleton
@Slf4j
public class LivestreamManager
{
	private static final Duration LIVE_SOUND_MAX_AGE = Duration.ofMinutes(180);

	private Livestream livestream = null;
	private int lastChecked = -1;
	private int lastSentMessage = -1;
	private boolean offlineAnnouncementSent = false;
	private boolean suppressLiveTransitionSound = false;

	@Inject
	private Client client;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private OphidiavenomConfig config;

	@Inject
	private ChatRightClickManager chatRightClickManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private LivestreamLiveSound livestreamLiveSound;

	public void onGameTick(GameTick gameTick)
	{
		if (!config.livestream())
		{
			return;
		}

		handleTickReset();
		sendLiveLivestreamMessage(false);

		int currentTick = client.getTickCount();
		if (lastChecked == -1 || currentTick < lastChecked || currentTick - lastChecked > 100)
		{
			executor.submit(() -> {
				sendRequest(currentTick);
			});

			lastChecked = currentTick;
		}
	}

	public void resetStateForWorldHopOrLogin()
	{
		// Reset poll/message timing so we immediately refresh after state transitions.
		// Keep the last livestream snapshot so hop/login doesn't count as a live transition.
		lastChecked = -1;
		lastSentMessage = -1;
		//suppressLiveTransitionSound = true;
	}
	public static long extract(String text, String regex)
	{

		Matcher matcher = Pattern.compile(regex).matcher(text);
		if (matcher.find())
		{
			return Long.parseLong(matcher.group(1));
		}
		return 0;
	}

	public static Duration parseUptimeToDuration(String uptime)
	{
		String text = uptime.toLowerCase();

		long hours = extract(text, "(\\d+)\\s*hour");
		long minutes = extract(text, "(\\d+)\\s*minute");
		long seconds = extract(text, "(\\d+)\\s*second");

		if (hours == 0 && minutes == 0 && seconds == 0)
		{
			return null;
		}

		return Duration.ofHours(hours)
				.plusMinutes(minutes)
				.plusSeconds(seconds);
	}

	private void sendRequest(final int currentTick)
	{

		String title = "";
		String uptime = "";
		Boolean live = false;

		Request request = new Request.Builder().url("https://decapi.me/twitch/status/ophidiavenom").build();

		try (Response response = okHttpClient.newCall(request).execute()) {
			if (!response.isSuccessful() || response.body() == null) {
				return;
			}
			else {
				title = response.body().string();

			}
			response.close();
		}
		catch(IOException e)
			{

				return;
			}
        catch(Exception e)
			{

				return;
			}

		Request request2 = new Request.Builder().url("https://decapi.me/twitch/uptime/ophidiavenom").build();

		try (Response response2 = okHttpClient.newCall(request2).execute()) {
			if (!response2.isSuccessful() || response2.body() == null) {

				return;

			}
			else {
				String val = response2.body().string();
				if (val.contains("offline")) {

					live = false;
				} else {

					live = true;

					Duration duration = parseUptimeToDuration(val);

					if (duration == null) {
						return;
					}

					uptime = Instant.now().minus(duration).truncatedTo(ChronoUnit.MINUTES).toString();

					}

				}
			response2.close();
			}

		catch(IOException e)
		{
			return;
		}
		catch(Exception e)
		{
			return;
		}

		StringBuilder jsonResponse = new StringBuilder("{");
		jsonResponse.append("\n");
		jsonResponse.append("\"live\": ");
		jsonResponse.append(live.toString());
		jsonResponse.append(",");
		jsonResponse.append("\n");
		jsonResponse.append("\"title\": ");
		jsonResponse.append("\"").append(title).append("\"");
		jsonResponse.append(",");
		jsonResponse.append("\n");
		jsonResponse.append("\"wentLiveAt\": ");
		jsonResponse.append("\"").append(uptime).append("\"");
		jsonResponse.append("\n");
		jsonResponse.append("}");

		Livestream newLivestream = gson.fromJson(jsonResponse.toString(), Livestream.class);

		if (newLivestream == null)
		{
			return;
		}

		if (livestream != null &&
			newLivestream.isLive() == livestream.isLive() &&
			Objects.equals(newLivestream.getTitle(), livestream.getTitle()) &&
			Objects.equals(newLivestream.getWentLiveAt(), livestream.getWentLiveAt()))
		{
			lastChecked = currentTick;
			return;
		}

		final Livestream previousLivestream = livestream;
		final boolean wasLive = previousLivestream != null && previousLivestream.isLive();
		final boolean isLive = newLivestream.isLive();
		final boolean becameOffline = previousLivestream != null && wasLive && !isLive;

		livestream = newLivestream;
		clientThread.invokeLater(() -> {
			if (isLive)
			{
				sendLiveLivestreamMessage(true);
			}
			if (shouldPlayLiveSound(previousLivestream, newLivestream, suppressLiveTransitionSound))
			{
				offlineAnnouncementSent = false;
				suppressLiveTransitionSound = true;
				livestreamLiveSound.playSound();
			}
			else if (becameOffline && !offlineAnnouncementSent)
			{
				sendOfflineLivestreamMessage();
				offlineAnnouncementSent = true;
				suppressLiveTransitionSound = false;
			}
		});
	}


	private void sendLiveLivestreamMessage(boolean force)
	{
		final int currentTick = client.getTickCount();

		// Only send once every x minutes, unless we force send (in case he goes live)
		if (!force &&
			lastSentMessage != -1 &&
			currentTick >= lastSentMessage &&
			currentTick - lastSentMessage < config.livestreamInterval() * 100)
		{
			return;
		}

		// Only send if OphidiaVenom is live
		if (livestream == null || !livestream.isLive())
		{
			return;
		}

		lastSentMessage = currentTick;

		ChatMessageBuilder chatMessage = new ChatMessageBuilder();
		String hex = Integer.toHexString(config.livestreamColor().getRGB()).substring(2);
		final String title = livestream.getTitle() == null ? "" : livestream.getTitle().trim();
		chatMessage
			.append(ChatColorType.NORMAL)
			.append("OphidiaVenom is live! ");

		if (!title.isEmpty())
		{
			chatMessage
				.append(ChatColorType.HIGHLIGHT)
				.append(title);
		}

		queueLivestreamMessage(chatMessage.build(), hex);
	}

	private void sendOfflineLivestreamMessage()
	{
		ChatMessageBuilder chatMessage = new ChatMessageBuilder();
		chatMessage
			.append(ChatColorType.HIGHLIGHT)
			.append("OphidiaVenom went offline.");

		String hex = Integer.toHexString(config.livestreamColor().getRGB()).substring(2);
		queueLivestreamMessage(chatMessage.build(), hex);
	}

	private void queueLivestreamMessage(String chatMessage, String hex)
	{
		String message = chatMessage.replaceAll("colHIGHLIGHT", "col=" + hex);
		RightClickAction rightClickAction = new RightClickAction("Open Livestream", "https://twitch.tv/ophidiavenom");
		chatRightClickManager.putInMap(message, rightClickAction);
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	private boolean shouldPlayLiveSound(
		Livestream previousLivestream,
		Livestream newLivestream,
		boolean wasSuppressingLiveSound)
	{
		if (!config.livestreamPlaySound() || wasSuppressingLiveSound || !newLivestream.isLive())
		{
			return false;
		}

		final Instant newWentLiveAt = parseWentLiveAt(newLivestream.getWentLiveAt());
		if (newWentLiveAt == null)
		{
			return false;
		}

		final Instant previousWentLiveAt = parseWentLiveAt(
			previousLivestream == null ? null : previousLivestream.getWentLiveAt());
		if (Objects.equals(newWentLiveAt, previousWentLiveAt))
		{
			return false;
		}

		final Duration age = Duration.between(newWentLiveAt, Instant.now());
		return !age.isNegative() && age.compareTo(LIVE_SOUND_MAX_AGE) <= 0;
	}

	private static Instant parseWentLiveAt(String wentLiveAt)
	{
		if (wentLiveAt == null || wentLiveAt.isEmpty())
		{
			return null;
		}

		try
		{
			return Instant.parse(wentLiveAt);
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}

	private void handleTickReset()
	{
		final int currentTick = client.getTickCount();
		if (lastChecked != -1 && currentTick < lastChecked)
		{
			lastChecked = -1;
		}
		if (lastSentMessage != -1 && currentTick < lastSentMessage)
		{
			lastSentMessage = -1;
		}
	}

	public boolean onConfigChanged (ConfigChanged configChanged)
	{
		if (config.livestreamPlaySound() && configChanged.getKey().equals("livestreamPlaySound")) {
			livestreamLiveSound.playSound();
			return true;
		}
		return false;
	}
}

package com.github.honestlygroovy.ophidiavenom.livestreams;

import lombok.Getter;

public class Livestream
{
	@Getter
	private boolean live;

	@Getter
	private String title;

	@Getter
	private String wentLiveAt;
}

package com.github.honestlygroovy.ophidiavenom;

import java.io.BufferedInputStream;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.util.regex.Pattern;
import net.runelite.client.RuneLite;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

public class PlayerKillLineManager
{
	private static final HttpUrl RAW_GITHUB = HttpUrl.parse("https://raw.githubusercontent.com/HonestlyGroovy/ophidiavenom-sounds/playerkillpatterns");
	private static final String USERS_FILENAME = "pklines.txt";
	private static Pattern[] patterns = null;

	public static void Setup(final OkHttpClient okHttpClient)
	{
		HttpUrl usersUrl = RAW_GITHUB.newBuilder().addPathSegment(USERS_FILENAME).build();
		try (Response res = okHttpClient.newCall(new Request.Builder().url(usersUrl).build()).execute())
		{
			if (res.body() != null)
			{
				String[] lines = res.body().string().split("\n");
				patterns = new Pattern[lines.length];

				for (int i = 0; i < lines.length; i++)
				{
					patterns[i] = Pattern.compile(lines[i]);
				}
			}
		}
		catch (IOException e)
		{
			return;
		}
	}

	public static Pattern[] getPatterns()
	{
		return patterns;
	}
}

