import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.client.events.ConfigChanged;

@Singleton
@Slf4j
public class ToaChestLight
{
	@Inject
	private Client client;

	@Inject
	private OphidiavenomConfig config;

	@Inject
	private SoundEngine soundEngine;

	@Inject
	private ScheduledExecutorService executor;

	private static final int VARBIT_VALUE_CHEST_KEY = 2;
	private static final int VARBIT_ID_SARCOPHAGUS = 14373;

	private static final int GAME_ID_SARCOPHAGUS = 46220;

	private static final int[] VARBIT_MULTILOC_IDS_CHEST = new int[]{
			14356, 14357, 14358, 14359, 14360, 14370, 14371, 14372
	};

	private boolean sarcophagusIsPurple;
	private boolean purpleIsMine = true;

	public void onGameObjectSpawned(GameObjectSpawned e)
	{
		if ((!config.toaPurpleChest() && !config.toaWhiteChest()) || e.getGameObject().getId() != GAME_ID_SARCOPHAGUS)
		{
			return;
		}

		log.debug("Sarcophagus spawned");
		log.debug(String.valueOf(e.getGameObject().getId()));
		parseVarbits();
		log.debug(String.valueOf(sarcophagusIsPurple));
		log.debug(String.valueOf(purpleIsMine));

		if (sarcophagusIsPurple)
		{
			if (config.toaPurpleChest())
			{
				if (purpleIsMine)
				{
					log.debug("Playing ToA your purple chest");
					soundEngine.playClip(Sound.YOUR_PURPLE, executor);
				}
				else
				{
					log.debug("Playing ToA not your purple chest");
					soundEngine.playClip(Sound.NOT_YOUR_PURPLE, executor);
				}
			}
		}
		else if (config.toaWhiteChest())
		{
			log.debug("Playing ToA white chest");
			soundEngine.playClip(Sound.WHITE_LIGHT_AFTER_RAID, executor);
		}
	}

	private void parseVarbits()
	{
		sarcophagusIsPurple = client.getVarbitValue(VARBIT_ID_SARCOPHAGUS) % 2 != 0;
		purpleIsMine = true;

		for (final int varbitId : VARBIT_MULTILOC_IDS_CHEST)
		{
			if (client.getVarbitValue(varbitId) == VARBIT_VALUE_CHEST_KEY)
			{
				purpleIsMine = false;
				break;
			}
		}
	}

	public boolean onConfigChanged (ConfigChanged configChanged)
	{
		if (config.toaWhiteChest() && configChanged.getKey().equals("toaWhiteChest")) {
			soundEngine.playClip(Sound.WHITE_LIGHT_AFTER_RAID, executor);
			return true;
		}
		else if (config.toaPurpleChest() && configChanged.getKey().equals("toaPurpleChest")) {
			soundEngine.playClip(Sound.YOUR_PURPLE, executor);
			return true;
		}
		return false;
	}
}

package com.github.honestlygroovy.ophidiavenom.sounds;

import com.github.honestlygroovy.ophidiavenom.OphidiavenomConfig;
import com.github.honestlygroovy.ophidiavenom.Sound;
import com.github.honestlygroovy.ophidiavenom.SoundEngine;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.client.events.ConfigChanged;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;

import static com.github.honestlygroovy.ophidiavenom.OphidiavenomPlugin.OPHIDIAVENOM;

@Singleton
@Slf4j
public class LevelUp
{
	@Inject
	private Client client;

	@Inject
	private OphidiavenomConfig config;

	@Inject
	private SoundEngine soundEngine;

	@Inject
	private ScheduledExecutorService executor;
	//: Change to match audio file
	private static final String message = "Level up: completed.";
	private static final String level99Message = "Level 99: completed.";

	private final Map<Skill, Integer> oldExperience = new EnumMap<>(Skill.class);

	public void onStatChanged(StatChanged statChanged)
	{
		final Skill skill = statChanged.getSkill();

		// Modified from Nightfirecat's virtual level ups plugin as this info isn't (yet?) built in to statChanged event
		final int xpAfter = client.getSkillExperience(skill);
		final int levelAfter = Experience.getLevelForXp(xpAfter);
		final int xpBefore = oldExperience.getOrDefault(skill, -1);
		final int levelBefore = xpBefore == -1 ? -1 : Experience.getLevelForXp(xpBefore);

		oldExperience.put(skill, xpAfter);

		// Do not proceed if any of the following are true:
		//  * xpBefore == -1              (don't fire when first setting new known value)
		//  * xpAfter <= xpBefore         (do not allow 200m -> 200m exp drops)
		//  * levelBefore >= levelAfter   (stop if if we're not actually reaching a new level)
		//  * levelAfter > MAX_REAL_LEVEL && config says don't include virtual (level is virtual and config ignores virtual)
		if (xpBefore == -1 || xpAfter <= xpBefore || levelBefore >= levelAfter ||
			(levelAfter > Experience.MAX_REAL_LEVEL && !config.announceLevelUpIncludesVirtual()))
		{
			return;
		}

		// Hitting level 99 in a skill is a milestone and gets its own sound/announcement,
		// taking precedence over the generic level-up sound for that single event.
		final boolean justReached99 = levelBefore < Experience.MAX_REAL_LEVEL
			&& levelAfter >= Experience.MAX_REAL_LEVEL;

		if (justReached99 && config.announceLevel99())
		{
			if (config.showChatMessages())
			{
				client.addChatMessage(ChatMessageType.PUBLICCHAT, OPHIDIAVENOM, level99Message, null);
			}
			soundEngine.playClip(Sound.LEVEL_99, executor);
			return;
		}

		if (config.announceLevelUp())
		{
			if (config.showChatMessages())
			{
				client.addChatMessage(ChatMessageType.PUBLICCHAT, OPHIDIAVENOM, message, null);
			}
			soundEngine.playClip(Sound.LEVEL_UP, executor);
		}
	}

	public void clear()
	{
		oldExperience.clear();
	}

	public void setOldExperience()
	{
		for (final Skill skill : Skill.values())
		{
			oldExperience.put(skill, client.getSkillExperience(skill));
		}
	}

	public boolean onConfigChanged (ConfigChanged configChanged)
	{
		if (config.announceLevelUp() && configChanged.getKey().equals("announceLevelUp")) {
			soundEngine.playClip(Sound.LEVEL_UP, executor);
			return true;
		}
		else if (config.announceLevel99() && configChanged.getKey().equals("announceLevel99")) {
			soundEngine.playClip(Sound.LEVEL_99, executor);
			return true;
		}
		return false;
	}
}

package com.github.honestlygroovy.ophidiavenom;


import com.github.honestlygroovy.ophidiavenom.livestreams.LivestreamManager;
